parameters.jsCode:
const raw = $input.first()?.json ?? {};
const input = raw.body ?? raw.payload ?? raw;

const item = Array.isArray(input.items) ? input.items[0] : undefined;

const pr =
  input.pull_request ??
  input.pr ??
  item ??
  input;

const prNumber =
  pr.number ??
  input.number ??
  input.pull_number ??
  input.pr_number;

const sha =
  pr.head?.sha ??
  input.head?.sha ??
  input.after ??
  input.sha;

const repoFullName =
  input.repository?.full_name ??
  input.repo ??
  input.full_name ??
  'div0rce/cherry';

const [owner, repo] = String(repoFullName).split('/');

if (!prNumber) {
  return [{
    json: {
      ok: false,
      status: 'failed',
      workflow: '09_docs_drift_detector',
      error: 'missing_pr_number',
      reason: 'Normalize PR could not derive a PR number from webhook, search, or flat payload',
      receivedKeys: Object.keys(input),
      totalCount: input.total_count,
      searchType: input.search_type,
      repoFullName,
      actions: ['do_not_classify_pr']
    },
  }];
}

const labels = Array.isArray(pr.labels)
  ? pr.labels.map((label) => typeof label === 'string' ? label : label.name).filter(Boolean)
  : [];

return [{
  json: {
    ...input,
    event: 'github.pull_request_docs_drift',
    source: 'github',
    owner: owner || input.repository?.owner?.login || 'div0rce',
    repo: repoFullName,
    repoName: repo || input.repository?.name || 'cherry',
    repoFullName,
    prNumber,
    sha,
    title: pr.title ?? input.title ?? '',
    body: pr.body ?? input.body ?? '',
    labels,
    timestamp: raw.timestamp ?? input.workflow_run?.updated_at ?? pr.updated_at ?? input.issue?.updated_at ?? new Date().toISOString(),
    workflow: '09_docs_drift_detector',
    ok: true,
    status: 'accepted',
    summary: 'Normalized github.pull_request_docs_drift.',
    actions: [],
    pull_request: {
      number: prNumber,
      title: pr.title ?? input.title ?? '',
      body: pr.body ?? input.body ?? '',
      head: { sha },
      labels: Array.isArray(pr.labels) ? pr.labels : [],
    },
    payload: {
      ...input,
      repository: input.repository ?? { full_name: repoFullName, name: repo || input.repository?.name || 'cherry', owner: { login: owner || input.repository?.owner?.login || 'div0rce' } },
      pull_request: {
        number: prNumber,
        title: pr.title ?? input.title ?? '',
        body: pr.body ?? input.body ?? '',
        head: { sha },
        labels: Array.isArray(pr.labels) ? pr.labels : [],
      }
    }
  },
}];

const event = $input.first()?.json ?? {};
const missing = [];
if (!event.prNumber) missing.push('prNumber');
if (!event.sha) missing.push('sha');
const output = {
  ...event,
  valid: missing.length === 0,
  validationErrors: missing,
  status: missing.length === 0 ? event.status : 'failed',
  summary: missing.length === 0 ? event.summary : 'Payload missing required fields: ' + missing.join(', '),
  actions: missing.length === 0 ? event.actions : [...(event.actions ?? []), 'do_not_classify_pr']
};
return [{ json: output }];

const prEvent = $node['Normalize PR'].json;
const classification = $input.first()?.json ?? {};
const classifierOutput = classification.classifierOutput ?? {};
const docsDrift = classifierOutput.docsDrift ?? {};
const statusRequests = Array.isArray(classifierOutput.statusRequests) ? classifierOutput.statusRequests : [];
const statusRequest = statusRequests.find((request) => request.context === 'cherry/docs-drift');
const sha = prEvent.sha;
const domains = Array.isArray(docsDrift.domains) ? docsDrift.domains : [];
const labels = Array.isArray(docsDrift.labels) ? docsDrift.labels : [];
const drift = docsDrift.drift === true;
const output = {
  ...prEvent,
  sha,
  automationEventId: classification.automationEventId,
  outputHash: classification.outputHash,
  cherryClassifierOutput: classifierOutput,
  docsDrift,
  statusRequest,
  labelBody: { labels },
  commentBody: { body: 'Cherry docs drift detector.\n\n' + (drift ? 'Docs update required for changed domains: ' + domains.join(', ') : 'Cherry found no docs drift.') + '\n\nDocs must match code reality unless legal constraints require a code fix.' },
  status: drift ? 'accepted' : 'ignored',
  summary: drift ? 'Cherry detected docs drift for ' + domains.join(', ') + '.' : 'Cherry found no docs drift.',
  actions: drift ? ['classify_pr_in_cherry', 'post_docs_status', 'label_docs_drift', 'comment_required_docs_update'] : ['classify_pr_in_cherry', 'post_docs_status']
};
return [{ json: output }];

const event = $input.first()?.json ?? {};
const missing = [];

if (!event.statusRequest) missing.push('statusRequest');
if (!event.repo) missing.push('repo');
if (!event.sha) missing.push('sha');
if (!event.outputHash) missing.push('outputHash');
if (!event.cherryClassifierOutput?.classifierVersion) missing.push('classifierVersion');

if (missing.length > 0) {
  return [{
    json: {
      ok: false,
      workflow: event.workflow,
      status: 'failed',
      summary: 'Cherry status payload missing required fields. Refusing to post status.',
      actions: ['do_not_post_status'],
      missing
    }
  }];
}

return [{ json: event }];

const event = $input.first()?.json ?? {};
const output = { ...event, workflow: event.workflow ?? '09_docs_drift_detector', sinkRouting: {
  discord: '{{ $env.DISCORD_WEBHOOK_URL }}', slack: '{{ $env.SLACK_WEBHOOK_URL }}', email: '{{ $env.EMAIL_WEBHOOK_URL }}', notion: '{{ $env.NOTION_WEBHOOK_URL }}', googleSheets: '{{ $env.GOOGLE_SHEETS_WEBHOOK_URL }}', linearJira: '{{ $env.LINEAR_JIRA_WEBHOOK_URL }}', githubProjects: '{{ $env.GITHUB_PROJECTS_WEBHOOK_URL }}', archive: '{{ $env.CHERRY_API_BASE_URL }}/api/automation/events', incidentTimeline: '{{ $env.CHERRY_API_BASE_URL }}/api/automation/incident-timeline' } };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ok: event.ok !== false, workflow: event.workflow, status: event.status ?? 'accepted', summary: event.summary ?? 'Docs drift handled.', actions: event.actions ?? [] };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ok: event.ok !== false, workflow: event.workflow, status: 'ignored', summary: event.summary ?? 'No docs drift detected.', actions: event.actions ?? [] };
return [{ json: output }];

const items = $input.all();

let files = [];

for (const item of items) {
  const json = item.json;

  if (Array.isArray(json)) {
    files.push(...json);
  } else if (Array.isArray(json.files)) {
    files.push(...json.files);
  } else if (Array.isArray(json.data)) {
    files.push(...json.data);
  } else if (json && json.filename) {
    files.push(json);
  }
}

files = files.map((file) => ({
  filename: file.filename ?? file.path ?? file.name ?? '',
  status: file.status ?? 'modified',
  additions: Number(file.additions ?? 0),
  deletions: Number(file.deletions ?? 0),
  changes: Number(file.changes ?? 0),
  patch: String(file.patch ?? '')
})).filter((file) => file.filename.length > 0);

return [{
  json: {
    ...($items('Normalize PR')[0]?.json ?? {}),
    files
  }
}];

